/* Profile and tokens prototype: the shell's own pages (PT1 to PT5), and a controls bar to reach their states. */
window.START_ROUTE = 'profile'; window.INWORLD = () => null;
const PBp = (k, v, t, on) => `<button type="button" data-p="${k}" data-v="${v}" aria-pressed="${on}">${t}</button>`;
window.PROTO_EXT = () => `<span class="group"><b>Go to</b>${[['profile', 'Profile'], ['tokens', 'Access tokens'], ['device/KHWT-QPLM', 'Connect, with a code'], ['device', 'Connect, no code'], ['device/NOPE', 'Connect, wrong code'], ['device/KHWT-QPLM/signin', 'Connect, not signed in']].map(([v, t]) => PBp('ptgo', v, t, false)).join('')}</span><span class="group"><b>Tokens</b>${PBp('pttk', 'none', 'None', false)}${PBp('pttk', 'some', 'Five', false)}</span>`;
window.PROTO_SYNC = () => {};
window.PROTO_CLICK = (k, v) => { if (k === 'ptgo') { SA.done = false; go(v); return true; } if (k === 'pttk') { SA.tokens = v === 'none' ? [] : [{ id: 't1', name: 'Laptop command line', hint: 'x3Qf', made: 90, used: 0, ends: null }, { id: 't2', name: 'Phone', hint: 'k9Lm', made: 200, used: 21, ends: 4 }, { id: 't3', name: 'Build server script', hint: 'p7Zr', made: 300, used: 120, ends: null }, { id: 't4', name: 'Old laptop', hint: 'b2Vd', made: 270, used: null, ends: null }, { id: 't5', name: 'Conference demo', hint: 'q8Wn', made: 150, used: 60, ends: -21 }]; go('tokens'); render(true); return true; } return false; };
